interface CompraPublica {
  tipoNorma: string;
  denominacion: string;
  nombreTitulo: string;
  numero: string;
  fecha: string;
  fechaPublicacion: string;
  tieneEfectosGenerales: string;
  ultimaActualizacion: string;
  descripcion: string;
  enlaceModificacion: string;
  textoEnlacePublicacion?: string;
  cantidadEnlacesModificacion?: number;
}

type FilaCompraPublica = [
  numero: string,
  fecha: string,
  nombreTitulo: string,
  descripcion: string,
  opciones?: Partial<CompraPublica>
];

const fechaPublicacionPorMes: Record<string, string> = {
  '01': '05.02.2016, Página Web',
  '02': '05.03.2016, Página Web',
  '03': '05.04.2016, Página Web',
  '04': '05.05.2016, Página Web',
  '05': '03.06.2016, Página Web'
};

const fechaPublicacion2013 = (fecha: string): string => {
  const dia = Number(fecha.slice(0, 2));
  const mes = Number(fecha.slice(3, 5));

  if (mes < 2 || (mes === 2 && dia <= 13)) return '01.03.2013 Página Web';
  if (mes < 3 || (mes === 3 && dia <= 8)) return '15.03.2013 Página Web';
  if (mes < 4 || (mes === 4 && dia <= 8)) return '05.04.2013 Página Web';
  if (mes === 4) return '03.05.2013 Página Web';
  if (mes < 6 || (mes === 6 && dia <= 20)) return '21.06.2013 Página Web';
  if (mes < 7 || (mes === 7 && dia === 1)) return '02.07.2013 Página Web';
  if (mes < 8 || (mes === 8 && dia <= 7)) return '09.08.2013 Página Web';
  if (mes === 8 && dia <= 21) return '22.08.2013 Página Web';
  if (mes === 8 || (mes === 9 && dia <= 2)) return '06.09.2013 Página Web';
  if (mes === 9 || (mes === 10 && dia <= 1)) return '06.10.2013 Página Web';
  if (mes === 10 || (mes === 11 && dia <= 5)) return '06.11.2013 Página Web';
  if (mes === 11) return '06.12.2013 Página Web';
  return '06.01.2014 Página Web';
};

const crearComprasPublicas = (
  filas: FilaCompraPublica[],
  anioPublicacion = '2016',
  tipoNormaPorDefecto = 'Decretos Alcaldicios'
): CompraPublica[] =>
  filas.map(([numero, fecha, nombreTitulo, descripcion, opciones = {}]) => ({
    tipoNorma: opciones.tipoNorma ?? tipoNormaPorDefecto,
    denominacion: 'Contratación de Servicio',
    numero,
    fecha,
    fechaPublicacion: opciones.fechaPublicacion ?? (
      anioPublicacion === '2015'
        ? fecha.slice(3, 5) === '12' && Number(fecha.slice(0, 2)) >= 10
          ? '06.01.2016 Página Web'
          : `${fecha.slice(3, 5) === '12' ? '10' : '06'}.${fecha.slice(3, 5) === '12' ? '12' : String(Number(fecha.slice(3, 5)) + 1).padStart(2, '0')}.${anioPublicacion} Página Web`
        : anioPublicacion === '2013'
          ? fechaPublicacion2013(fecha)
          : anioPublicacion === '2014'
          ? `06.${String(Number(fecha.slice(3, 5)) === 12 ? 1 : Number(fecha.slice(3, 5)) + 1).padStart(2, '0')}.${Number(fecha.slice(3, 5)) === 12 ? '2015' : '2014'} Página Web`
        : fechaPublicacionPorMes[fecha.slice(3, 5)] ?? ''
    ),
    nombreTitulo,
    tieneEfectosGenerales: 'No',
    ultimaActualizacion: 'Sin Modificaciones',
    descripcion,
    enlaceModificacion: 'Sin Modificaciones',
    ...opciones
  }));

